        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'STAT-METHODS-EXPERIMENTAL-DESIGN-BASIC-V2'],
            [
                'module_no' => 8,
                'title' => 'Statistical Methods & Experimental Design',
                'year_level' => 'Year 2',
                'version_no' => 2,
                'version_name' => 'Statistical Methods & Experimental Design Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'ANOVA, regression analysis, experimental design principles, sampling strategies, and inferential testing. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 660,
                'sort_order' => 23,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'STAT-METHODS-EXPERIMENTAL-DESIGN-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'STAT-METHODS-EXPERIMENTAL-DESIGN-BASIC-V2')
